#!/usr/bin/env bash
# Tags de personnes sur les médias : backend (table, verdicts, procédures admin, relance).
# Prérequis : apply-docs-comptes-demo.sh. MIGRATION : 20261214000000_media_people.
# Usage (racine du repo) : bash apply-fix-tags-backend.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/index.ts" 2>/dev/null | grep -qF "mediaPeople: mediaPeopleRouter"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "mineur@akfc.demo" "apps/web/content/docs/dev/demarrer/mise-en-route.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-comptes-demo.sh puis apply-docs-comptes-demo.sh"; exit 1; }
MODIFIED=("e2e/data.mjs" "e2e/prepare.mjs" "e2e/tutos-admin.spec.ts" "packages/backend/src/modules/index.ts" "packages/backend/src/modules/privacy/exportMyData.service.ts" "prisma/schema.prisma")
CREATED=("e2e/tags-personnes.spec.ts" "packages/backend/src/email/templates/imageConsentReminder.ts" "packages/backend/src/modules/mediaPeople/mediaPeople.service.ts" "packages/backend/src/modules/mediaPeople/router.ts" "packages/contracts/src/legal/mediaPeople.ts" "prisma/migrations/20261214000000_media_people/migration.sql")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "prisma/migrations/20261214000000_media_people" 2>/dev/null || true; rmdir -p "packages/backend/src/modules/mediaPeople" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "mediaPeople: mediaPeopleRouter" "packages/backend/src/modules/index.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "e2e"
