trap - ERR

[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
node scripts/build-procedure-map.mjs --write >/dev/null 2>&1 || { echo "❌ carte des procédures : échec"; restore; exit 1; }
echo "== prisma generate =="
if ! pnpm prisma generate > /tmp/akfc_pg.log 2>&1; then echo "❌ prisma generate ÉCHOUÉ :"; tail -8 /tmp/akfc_pg.log; restore; pnpm prisma generate >/dev/null 2>&1 || true; exit 1; fi
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && node scripts/check-doc-entities.mjs && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ |ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; pnpm prisma generate >/dev/null 2>&1 || true; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}" apps/web/src/features/docs/entities/procedureMap.generated.json
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
Tags de personnes sur les médias (backend), comparés au droit à l'image

- MediaPerson : qui apparaît sur quel média, posé à la main par un admin
  (jamais de reconnaissance faciale) ; supprimé avec le média ou le compte
- MediaAsset.noRecognizablePerson : « aucune personne reconnaissable »
- contrats mediaPeople.ts : état d'une personne par usage (formulaire le
  plus récent, sinon statut saisi par le club) et verdict d'un média (un
  refus l'emporte sur une absence de réponse) ; jamais stocké
- mediaPeople.forMedia / setTags / setNoRecognizable / verdicts / remind
  (admin) ; relance une fois tous les 7 jours (User.imageConsentRemindedAt) :
  nouveau lien au parent si une demande existe, sinon e-mail au membre
- export « mes données » : les médias où le membre est tagué
- migration 20261214000000_media_people : une table, deux colonnes ; aucun
  média retiré du site (tous « à taguer »)
- e2e : tags-personnes.spec.ts (échoue si une absence de réponse
  l'emportait sur un refus) ; tutos-admin : cellule exacte du mineur

